      SUBROUTINE ENRIC2CC     CALCULATES CONTRIBUTION FROM SECOND-ORDER TERMS C     TO THE FIRST ORDER MATRIX FROM A SHIFTED REFERENCEC     TRAJECTORYCC     LIST OF COMMON BLOCKSC      INCLUDE 'COACOM.CIN'      INCLUDE 'RA.CIN'      INCLUDE 'TA.CIN'C---------------------------------------------------------------------C      DO 100 J = 1, 5      IND = 0      DO 100 L2 = 1, 6      DO 100 L1 = 1, L2      IND = IND + 1      RA(J,L1) = RA(J,L1) + TA(J,IND)*COA(L2)      RA(J,L2) = RA(J,L2) + TA(J,IND)*COA(L1)  100 CONTINUEC      RETURN      END